import random,itertools

def remove_exact(topo, compute_nodes, root_caps):
    flow_graph=nx.DiGraph()
    flow_graph.add_nodes_from(topo.nodes())
    for a,b,d in topo.edges(data=True):
      c=d.get('capacity',0)
      if c>0:
        if flow_graph.has_edge(a,b): flow_graph[a][b]['capacity']+=c
        else: flow_graph.add_edge(a,b,capacity=c)
    D=sum(root_caps.values())
    flow_graph.add_node(SOURCE)
    for b in compute_nodes:
        if root_caps[b]>0: flow_graph.add_edge(SOURCE,b,capacity=root_caps[b])
        else: flow_graph.add_edge(SOURCE,b,capacity=0)
    edge_map={}
    comp=set(compute_nodes)
    switches=sorted(w for w in flow_graph.nodes() if w not in comp and w!=SOURCE)
    for w in switches:
        for u in sorted(list(flow_graph.predecessors(w))):
            if not flow_graph.has_edge(u,w): continue
            assert flow_graph[u][w]['capacity']>0
            for t in sorted(list(flow_graph.successors(w))):
                if not flow_graph.has_edge(w,t): continue
                assert flow_graph[w][t]['capacity']>0
                M=min(flow_graph[u][w]['capacity'], flow_graph[w][t]['capacity'])
                flow_graph.add_edge(u,SOURCE)
                cpct_ut=flow_graph[u][t]['capacity'] if flow_graph.has_edge(u,t) else 0
                assert cpct_ut>0 or not flow_graph.has_edge(u,t)
                if cpct_ut==0: flow_graph.add_edge(u,t)
                else: del flow_graph[u][t]['capacity']
                for v in compute_nodes:
                    if u==v or t==v: continue
                    cpct_vw=flow_graph[v][w]['capacity'] if flow_graph.has_edge(v,w) else 0
                    assert cpct_vw>0 or not flow_graph.has_edge(v,w)
                    if cpct_vw==0: flow_graph.add_edge(v,w)
                    else: del flow_graph[v][w]['capacity']
                    fval=nx.maximum_flow_value(flow_graph,u,w)-D
                    M=min(fval,M)
                    if cpct_vw==0: flow_graph.remove_edge(v,w)
                    else: flow_graph[v][w]['capacity']=cpct_vw
                    if M==0: break
                flow_graph.remove_edge(u,SOURCE)
                if M>0:
                    flow_graph.add_edge(w,SOURCE)
                    for v in compute_nodes:
                        if v!=u:
                            cpct_vt=flow_graph[v][t]['capacity'] if flow_graph.has_edge(v,t) else 0
                            assert cpct_vt>0 or not flow_graph.has_edge(v,t)
                            if cpct_vt==0: flow_graph.add_edge(v,t)
                            else: del flow_graph[v][t]['capacity']
                            fval=nx.maximum_flow_value(flow_graph,w,t)-D
                            if cpct_vt==0: flow_graph.remove_edge(v,t)
                            else: flow_graph[v][t]['capacity']=cpct_vt
                        else:
                            fval=nx.maximum_flow_value(flow_graph,w,t)-D
                        M=min(fval,M)
                        if M==0: break
                    flow_graph.remove_edge(w,SOURCE)
                if cpct_ut==0: flow_graph.remove_edge(u,t)
                else: flow_graph[u][t]['capacity']=cpct_ut
                if M==0: continue
                if (u,t) not in edge_map: edge_map[u,t]={}
                if w not in edge_map[u,t]: edge_map[u,t][w]=0
                edge_map[u,t][w]+=M
                flow_graph[u][w]['capacity']-=M
                flow_graph[w][t]['capacity']-=M
                if flow_graph.has_edge(u,t): flow_graph[u][t]['capacity']+=M
                elif u!=t: flow_graph.add_edge(u,t,capacity=M)
                if flow_graph[w][t]['capacity']==0: flow_graph.remove_edge(w,t)
                if flow_graph[u][w]['capacity']==0: break
            assert flow_graph[u][w]['capacity']==0, ('remain',w,u,flow_graph[u][w])
            flow_graph.remove_edge(u,w)
        assert flow_graph.out_degree(w)==flow_graph.in_degree(w)==0, ('deg',w)
    H=nx.DiGraph()
    H.add_nodes_from(compute_nodes)
    for a,b,d in flow_graph.edges(data=True):
       if a not in comp or b not in comp: continue
       c=d.get('capacity',0)
       if c>0:
         if H.has_edge(a,b): H[a][b]['capacity']+=c
         else: H.add_edge(a,b,capacity=c)
    # Check flow preservation
    def mf(G,roots):
      X=nx.DiGraph(G);X.add_node(SOURCE)
      for r,c in roots.items(): X.add_edge(SOURCE,r,capacity=c)
      return {v:nx.maximum_flow_value(X,SOURCE,v) for v in roots}
    return H,edge_map

